const TABLE = 'ae110169-3125-46e6-92cd-f431913e1b16';
const GEO_TABLE = '1ab29188-ed67-4fb3-9864-7be2613bf2e5';
const WS = constants.WS || 'ff5cb888-253b-40bc-8de7-6111d9195544';
const userEmail = (globals && globals.currentUser && globals.currentUser.email) || '';

const access = variables.access || {};
const isAdmin = !!(access.is && access.is.admin);
const isBuilder = !!(access.is && access.is.builder);
const isChecker = !!(access.is && access.is.checker);
const hasAllDomains = !!access.has_all_domains;
const hasAllGeos = !!access.has_all_geos;
const accessDomains = (Array.isArray(access.domains) ? access.domains : []).map(s => String(s).toLowerCase());
const accessGeos = (Array.isArray(access.geos) ? access.geos : []).map(s => String(s).toLowerCase());

const dom = (components.DomainFilter && components.DomainFilter.value) || '';
let st  = (components.StatusFilter && components.StatusFilter.value) || '';

async function fetchAllowedDomainNames() {
  if (isAdmin || isBuilder || hasAllDomains) return null;
  if (accessDomains.length === 0) return [];
  const r = await fetch(window.location.origin + '/api/tooljet-db/proxy/1687a012-ebd1-46a8-b648-ff13096f6b43?tj_app_id=not.is.null',
    { credentials: 'include', headers: { 'Tj-Workspace-Id': WS } });
  let rows;
  if (!r.ok) {
    const errText = await r.text();
    console.error('[SVC_FETCH] HTTP', r.status, r.statusText, 'URL=', r.url, 'body=', errText.slice(0, 500));
    rows = [];
  } else {
    const text = await r.text();
    try {
      rows = text ? JSON.parse(text) : [];
    } catch (parseErr) {
      console.error('[SVC_FETCH] JSON parse failed for URL=', r.url, 'body=', text.slice(0, 500), 'error=', parseErr);
      rows = [];
    }
  }
  const allNames = (Array.isArray(rows) ? rows : []).map(row => row.name).filter(Boolean);
  return allNames.filter(function (name) {
    const key = name.replace(/\s+/g, '_').toLowerCase();
    return accessDomains.includes(key);
  });
}

async function fetchAllowedGeoIds() {
  if (isAdmin || isBuilder || hasAllGeos) return null;
  if (accessGeos.length === 0) return [];
  const r = await fetch(window.location.origin + '/api/tooljet-db/proxy/' + GEO_TABLE + '?is_active=eq.true',
    { credentials: 'include', headers: { 'Tj-Workspace-Id': WS } });
  let rows;
  if (!r.ok) {
    const errText = await r.text();
    console.error('[SVC_FETCH] HTTP', r.status, r.statusText, 'URL=', r.url, 'body=', errText.slice(0, 500));
    rows = [];
  } else {
    const text = await r.text();
    try {
      rows = text ? JSON.parse(text) : [];
    } catch (parseErr) {
      console.error('[SVC_FETCH] JSON parse failed for URL=', r.url, 'body=', text.slice(0, 500), 'error=', parseErr);
      rows = [];
    }
  }
  const matches = (Array.isArray(rows) ? rows : []).filter(function (row) {
    const key = String(row.display_name || '').replace(/\s+/g, '_').toLowerCase();
    return accessGeos.includes(key);
  });
  console.log('[FETCH_GEO_IDS] accessGeos=', accessGeos, 'matched IDs=', matches.map(m => m.geo_region_id));
  return matches.map(function (row) { return row.geo_region_id; }).filter(function (v) { return v != null; });
}

function encodeIn(arr) {
  return '(' + arr.map(function (v) { return '"' + String(v).replace(/"/g, '\\"') + '"'; }).join(',') + ')';
}

function encodeIntIn(arr) {
  return '(' + arr.join(',') + ')';
}

async function buildUrl(statusValue) {
  const params = ['order=created_at.desc', 'limit=500'];

  if (dom) {
    params.push('domain=eq.' + encodeURIComponent(dom));
  } else {
    const allowed = await fetchAllowedDomainNames();
    if (allowed !== null) {
      if (allowed.length === 0) {
        if (statusValue !== 'MY_REQUEST' && statusValue !== 'APPROVED' && statusValue !== 'REJECTED' && statusValue !== 'AUTO_APPLIED') {
          params.push('domain=eq.__NO_ACCESS__');
        }
      } else {
        params.push('domain=in.' + encodeIn(allowed));
      }
    }
  }

  if (statusValue === 'MY_REQUEST') {
    if (userEmail) params.push('maker_email=eq.' + encodeURIComponent(userEmail));
  } else if (statusValue === 'APPROVED') {
    if (userEmail) params.push('maker_email=eq.' + encodeURIComponent(userEmail));
    params.push('status=eq.APPROVED');
  } else if (statusValue === 'REJECTED') {
    if (userEmail) params.push('maker_email=eq.' + encodeURIComponent(userEmail));
    params.push('status=eq.REJECTED');
  } else if (statusValue === 'AUTO_APPLIED') {
    if (userEmail) params.push('maker_email=eq.' + encodeURIComponent(userEmail));
    params.push('status=eq.AUTO_APPLIED');
  } else if (statusValue === 'MY_APPROVALS') {
    if (!isChecker && !isAdmin && !isBuilder) {
      params.push('id=eq.-1');
    } else {
      if (userEmail) params.push('maker_email=neq.' + encodeURIComponent(userEmail));
      params.push('status=eq.SUBMITTED');
      const allowedGeoIds = await fetchAllowedGeoIds();
      if (allowedGeoIds !== null) {
        if (allowedGeoIds.length === 0) {
          params.push('geo_region_id=is.null');
        } else {
          params.push('or=(geo_region_id.is.null,geo_region_id.in.' + encodeIntIn(allowedGeoIds) + ')');
        }
      }
    }
  } else if (statusValue === 'ALL') {
    if (isAdmin || isBuilder) {
    } else if (isChecker) {
      const meEq = userEmail ? 'maker_email.eq.' + userEmail : '';
      const allowedGeoIds = await fetchAllowedGeoIds();
      let geoPart = '';
      if (allowedGeoIds !== null) {
        if (allowedGeoIds.length === 0) {
          geoPart = ',geo_region_id.is.null';
        } else {
          geoPart = ',or(geo_region_id.is.null,geo_region_id.in.' + encodeIntIn(allowedGeoIds) + ')';
        }
      }
      const approvable = 'and(status.eq.SUBMITTED,maker_email.neq.' + (userEmail || '__none__') + geoPart + ')';
      if (meEq) {
        params.push('or=(' + meEq + ',' + approvable + ')');
      } else {
        params.push('status=eq.SUBMITTED');
        if (userEmail) params.push('maker_email=neq.' + encodeURIComponent(userEmail));
      }
    } else {
      if (userEmail) params.push('maker_email=eq.' + encodeURIComponent(userEmail));
    }
  } else if (statusValue) {
    params.push('status=eq.' + encodeURIComponent(statusValue));
  }

  /* MCB_V2 */ if (statusValue !== 'MY_REQUEST') {
    params.push('backend_sync_state=eq.SUCCESS');
  }
  return window.location.origin + '/api/tooljet-db/proxy/' + TABLE + '?' + params.join('&');
}

async function fetchRecords(statusValue) {
  const url = await buildUrl(statusValue);
  console.log('[SVC_FETCH] url=', url);
  const r = await fetch(url, { credentials: 'include', headers: { 'Tj-Workspace-Id': WS } });
  let data;
  if (!r.ok) {
    const errText = await r.text();
    console.error('[SVC_FETCH] HTTP', r.status, r.statusText, 'URL=', r.url, 'body=', errText.slice(0, 500));
    data = [];
  } else {
    const text = await r.text();
    try {
      data = text ? JSON.parse(text) : [];
    } catch (parseErr) {
      console.error('[SVC_FETCH] JSON parse failed for URL=', r.url, 'body=', text.slice(0, 500), 'error=', parseErr);
      data = [];
    }
  }
  return Array.isArray(data) ? data : [];
}

console.log('[SVC_FETCH] start dom=', dom, 'st=', st, 'userEmail=', userEmail, 'isAdmin=', isAdmin, 'isChecker=', isChecker, 'accessGeos=', accessGeos);
let records = await fetchRecords(st);
console.log('[SVC_FETCH] initial fetch records.length=', records.length);

if (!window._cr_initial_fallback_done && st === 'MY_APPROVALS' && records.length === 0) {
  window._cr_initial_fallback_done = true;
  st = 'MY_REQUEST';
  records = await fetchRecords(st);
  if (records.length === 0) {
    st = 'ALL';
    records = await fetchRecords(st);
  }
  try {
    if (components.StatusFilter && typeof components.StatusFilter.selectOption === 'function') {
      components.StatusFilter.selectOption(st);
    }
  } catch (e) {}
}

function ruleLevel(rec) {
  const intent = ((rec.payload && rec.payload.intent) || '').toLowerCase();
  if (intent.includes('global')) return 'Global';
  if (intent.includes('local')) return 'Local';
  if (intent === 'expire') {
    if (rec.payload && typeof rec.payload.is_global === 'boolean') return rec.payload.is_global ? 'Global' : 'Local';
    const nm = ((rec.payload && rec.payload.rule_name) || '').toLowerCase();
    if (nm.includes('local')) return 'Local';
    if (nm.includes('global')) return 'Global';
    return 'Local';
  }
  const cond = rec.payload && rec.payload.conditions;
  return (cond == null || (Array.isArray(cond) && cond.length === 0)) ? 'Global' : 'Local';
}

function intentLabel(intent) {
  const i = (intent || '').toLowerCase();
  if (i.indexOf('create') >= 0) return 'Create';
  if (i.indexOf('modify') >= 0) return 'Modify';
  if (i === 'expire') return 'Expire';
  if (i.indexOf('rollback') >= 0) return 'Rollback';
  return '';
}

function intentChip(label) {
  if (!label) return '';
  const palette = {
    Create:   {bg:'#eaf5ee', fg:'#1e6a45', border:'#bfe3cd'},
    Modify:   {bg:'#fff3e0', fg:'#8a5a1a', border:'#f5deb3'},
    Expire:   {bg:'#fdecec', fg:'#a52828', border:'#f4c0c0'},
    Rollback: {bg:'#ede7f6', fg:'#5e35b1', border:'#d1c4e9'},
  };
  const c = palette[label] || {bg:'#eef0f3', fg:'#5a6473', border:'#dde1e7'};
  return '<span style="display:inline-block;padding:1px 8px;border-radius:999px;background:' + c.bg
       + ';color:' + c.fg + ';border:1px solid ' + c.border
       + ';font-size:10px;font-weight:700;letter-spacing:0.02em;vertical-align:middle;margin-right:6px">' + label + '</span>';
}

function fmtDate(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d)) return String(iso);
  const pad = n => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate())
       + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}

function smallLevelChip(s) {
  const palette = {
    Global: {bg:'#fff7d6', fg:'#8a5a1a', border:'#f5deb3'},
    Local:  {bg:'#e0e7ff', fg:'#1c47cc', border:'#c7d2fe'},
  };
  const c = palette[s] || {bg:'#eef0f3', fg:'#5a6473', border:'#dde1e7'};
  return '<span style="display:inline-block;padding:1px 8px;border-radius:999px;background:' + c.bg
       + ';color:' + c.fg + ';border:1px solid ' + c.border
       + ';font-size:10px;font-weight:700;letter-spacing:0.02em;vertical-align:middle">' + s + '</span>';
}
function nameWithMeta(name, type) {
  function e(s){return String(s==null?'':s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  const eName = e(name);
  return '<div style="line-height:1.35;padding:6px 0;max-width:100%;overflow:hidden">'
       + '<div title="' + eName + '" style="font-weight:600;color:#1a2030;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + eName + '</div>'
       + '<div style="font-size:11px;color:#5a6473;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + e(type) + '</div>'
       + '</div>';
}

function typeBadges(level, intent) {
  const iLabel = intentLabel(intent);
  return '<div style="display:flex;flex-direction:row;align-items:center;gap:6px;padding:6px 0;flex-wrap:wrap">'
       + intentChip(iLabel)
       + smallLevelChip(level)
       + '</div>';
}

