console.log('[SVC_FETCH] final records.length=', records.length, 'sample=', records[0] && {id:records[0].id, status:records[0].status, domain:records[0].domain});
return records.map(rec => {
  const _type = rec.config_type || '—';
  const _level = ruleLevel(rec);
  const _name = (rec.payload && (rec.payload.config_name || rec.payload.rule_name)) || rec.config_record_id || '—';
  return {
